function link(raw){try{const u=new URL(raw);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}}
function key(raw){const l=link(raw);if(!l)return '';const u=new URL(l), a=/(?:\/dp\/|\/gp\/product\/)([a-z0-9]{10})(?:\/|$)/i.exec(u.pathname);return /(^|\.)amazon\./i.test(u.hostname)&&a?'asin:'+a[1].toUpperCase():u.origin+u.pathname.replace(/\/$/,'')+(u.searchParams.has('id')?'?id='+u.searchParams.get('id'):'')}
function canonical(raw){const k=key(raw);return k.startsWith('asin:')?'https://www.amazon.com/dp/'+k.slice(5):link(raw)}
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n||0);
const colors=['#f3df9b','#e0eac7','#c7e9e5','#f4d6cd','#e7dbf5','#d2e6f8'];
const field=(label,name,value='',type='text')=>'<label>'+e(label)+'<input name="'+name+'" type="'+type+'" '+(type==='number'?'step="any"':'')+' value="'+e(value)+'"></label>';
const area=(label,name,value='')=>'<label class="wide">'+e(label)+'<textarea name="'+name+'">'+e(value)+'</textarea></label>';
const opt=(values,v)=>values.map(x=>{const [k,l]=Array.isArray(x)?x:[x,x];return '<option value="'+e(k)+'" '+(k===v?'selected':'')+'>'+e(l)+'</option>'}).join('');
const select=(l,n,opts,v)=>'<label>'+e(l)+'<select name="'+n+'">'+opt(opts,v)+'</select></label>';
const button=(a,label,id='',cls='')=>'<button type="button" class="'+cls+'" data-act="'+a+'" data-id="'+e(id)+'">'+e(label)+'</button>';
const defaultTags=[['home','Home'],['tech','Technology'],['travel','Travel'],['inbox','Unsorted']].map(([id,name],i)=>({id,name,type:'category',color:colors[i],notes:'',mode:'ordered'}));
const defaultPeople=['Person 1','Person 2','Shared'];
function initial(){return {people:defaultPeople,tags:defaultTags,items:seed.items.map(make),notes:[],rules:{},overrides:{},recs:{},inventory:[],research:[],evidence:[],decisions:[],prefs:{hidden:false,archive:false},nickname:''}}
function make(obj={}){return {id:uid(),name:'',kind:'item',owner:'Shared',tags:[],parent:'',url:'',state:'Considering',hidden:false,archived:false,qty:1,price:null,store:'',attributes:[],description:'',...obj}}
let doc, device, page='guide', selected=new Set(), filter={q:'',tag:'',owner:'',parent:''}, preview=[], dragging='', reportGroup='Category', status='';
let searchQuery='', searchRows=[], searchDone=false, searchTruncated=false;
let hub=null, active=null, version=0, pending=false, userSettings={nickname:'',showHidden:false,showArchived:false};
const current=()=>doc?.state??doc?.history.at(-1)?.after??doc?.base;
const prefs=()=>({hidden:userSettings.stores?.[active?.id]?.showHidden??!!userSettings.showHidden,archive:!!userSettings.showArchived});
const editable=()=>active&&['editor','admin'].includes(active.role)&&!active.archived&&active.snapshotWritable!==false;
const controls=()=>active&&active.role==='admin';
const listed=x=>(userSettings.showArchived||!x.archived)&&(userSettings.showHiddenStores||!userSettings.stores?.[x.id]?.hidden);
async function call(path, data){const r=await fetch('/api/'+path,data===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const out=await r.json().catch(()=>({}));if(!r.ok){const err=Error(out.error||out.message||'Request failed ('+r.status+')');err.status=r.status;throw err;}return out}
async function steeringCommand(command){
 if(!active||pending)throw Error('Wait for the current store request to finish.');
 const store=active.id, view={...filter}, picks=[...selected];
 pending=true;
 try{
  const result=await call('stores/'+encodeURIComponent(store)+'/steering',{expectedVersion:version,command});
  await openStore(store);
  filter=view;selected=new Set(picks.filter(id=>current().items.some(item=>item.id===id)));
  status='Request saved. No external message was sent.';
  return result;
 } finally {pending=false;render();}
}
async function variantCommand(ids,options){
 if(!editable()||pending)throw Error('Open a writable store and wait for any pending edit.');
 const store=active.id,view={...filter},picks=[...selected];
 pending=true;
 try{
  const result=await call('stores/'+encodeURIComponent(store)+'/variants',{expectedVersion:version,commandId:uid(),ids,options});
  await openStore(store);filter=view;selected=new Set(picks.filter(id=>current().items.some(item=>item.id===id)));
  status='Saved the variant grouping without replacing existing item IDs.';
  return result;
 }finally{pending=false;render();}
}
function notice(t){status=t;render()}
async function act(fn){if(pending)return;pending=true;try{await fn()}catch(err){notice(err.message)}finally{pending=false;render()}}
async function setSettings(value){await act(async()=>{const a={...userSettings,...value};const out=await call('settings',a);userSettings=out.settings??a;if(active&&!listed(active))await boot();render()})}
function deviceId(){try{const x=localStorage.getItem('bedaway-device');if(x)return x;const v=uid();localStorage.setItem('bedaway-device',v);return v}catch{return uid()}}
function stores(){return hub?.stores??[]}
function storeLabel(s){return s.name+(s.id===hub.personalStoreId?' · Personal':s.id===hub.defaultSharedStoreId?' · Default shared':'')+(s.archived?' · Archived':'')+(userSettings.stores?.[s.id]?.hidden?' · Hidden':'')}
async function boot(preferred='',provided=null){hub=provided??await call('bootstrap');userSettings={nickname:'',showHidden:false,showArchived:false,...hub.settings};let remembered='';try{remembered=localStorage.getItem('bedaway-store')}catch{} const id=preferred||active?.id||remembered;const visible=stores().filter(listed);const match=visible.find(x=>x.id===id)||visible.find(x=>x.id===hub.defaultSharedStoreId)||visible.find(x=>x.id===hub.personalStoreId)||visible[0];if(match)await openStore(match.id);else{active=null;doc={schema:1,device,base:{...initial(),items:[],tags:[]},history:[],undo:[],redo:[]};render()}}
async function openStore(id){const out=await call('stores/'+encodeURIComponent(id));active={...stores().find(x=>x.id===id),...out.store,snapshotWritable:out.snapshotWritable??out.store?.snapshotWritable};version=out.version??0;const ev=(out.events??[]).slice().sort((a,b)=>(a.version??0)-(b.version??0));let base=ev[0]?.before??out.state??initial();doc={schema:1,device,base,state:out.state??base,history:ev,undo:[],redo:[]};for(const h of ev){if(h.operation==='change'){doc.undo.push(h.id);doc.redo=[]}else if(h.operation==='undo'){doc.undo=doc.undo.filter(x=>x!==h.target);doc.redo.push(h.target)}else if(h.operation==='redo'){doc.redo=doc.redo.filter(x=>x!==h.target);doc.undo.push(h.target)}}if(!ev.length)doc.base=out.state??initial();try{localStorage.setItem('bedaway-store',id)}catch{}selected.clear();filter={q:'',tag:'',owner:'',parent:''};render()}
async function start(){
 const fallback=deviceId();
 device=await new Promise(resolve=>{
  if(typeof indexedDB==='undefined'){resolve(fallback);return}
  let q;try{q=indexedDB.open('bedaway-browser-id',1)}catch{resolve(fallback);return}
  q.onupgradeneeded=()=>q.result.createObjectStore('identity');
  q.onerror=q.onblocked=()=>resolve(fallback);
  q.onsuccess=()=>{const db=q.result;let v=fallback;const t=db.transaction('identity','readwrite');const o=t.objectStore('identity');const a=o.get('id');
   a.onsuccess=()=>{if(typeof a.result==='string')v=a.result;else o.put(v,'id')};
   t.oncomplete=()=>{db.close();resolve(v)};t.onerror=t.onabort=()=>{db.close();resolve(fallback)}
  }
 });
 try{localStorage.setItem('bedaway-device',device)}catch{}
 return boot()
}
function apply(label,fn,operation='change',target=''){if(!editable()){notice('Open an active store where you have editor or admin access.');return}if(pending)return;const before=copy(current()),after=copy(before);fn(after);if(JSON.stringify(before)===JSON.stringify(after)){notice('Nothing changed.');return}const event={id:uid(),device,label,operation,target,before,after};act(async()=>{const saved=await call('stores/'+encodeURIComponent(active.id)+'/events',{expectedVersion:version,event});if(!saved.event){await openStore(active.id);return}version=saved.version;doc.state=saved.event.after;doc.history.push({...event,...saved.event});if(operation==='change'){doc.undo.push(event.id);doc.redo=[]}if(operation==='undo'){doc.undo.pop();doc.redo.push(target)}if(operation==='redo'){doc.redo.pop();doc.undo.push(target)}status='';render()})}
function replay(direction){const from=direction==='Undo'?doc.undo:doc.redo;if(!from.length)return;const id=from.at(-1),h=doc.history.find(x=>x.id===id);if(!h)return;const fromState=direction==='Undo'?h.after:h.before,toState=direction==='Undo'?h.before:h.after;apply(direction+': '+h.label,s=>{for(const k of diff(fromState,toState))if(k!=='steering')s[k]=patch(s[k],fromState[k],toState[k],true,k)},direction.toLowerCase(),id)}
function validBackup(d){return d?.schema===1&&d.base&&Array.isArray(d.history)&&[d.base,...d.history.flatMap(x=>[x?.before,x?.after])].every(s=>s&&Array.isArray(s.items)&&s.items.every(x=>typeof x?.id==='string'&&typeof x.name==='string'&&Array.isArray(x.tags)&&Array.isArray(x.attributes))&&Array.isArray(s.tags)&&Array.isArray(s.people)&&Array.isArray(s.notes)&&Array.isArray(s.inventory)&&s.prefs&&s.rules&&s.overrides&&s.recs)&&Array.isArray(d.undo)&&Array.isArray(d.redo)}
function dlg(title,body,fn,label='Save'){form.innerHTML='<h2>'+e(title)+'</h2><div class="formgrid">'+body+'</div><hr><div class="row"><button type="submit" class="primary">'+e(label)+'</button>'+button('close','Cancel')+'</div>';form.onsubmit=ev=>{ev.preventDefault();try{if(fn(Object.fromEntries(new FormData(form)))!==false)modal.close()}catch(err){alert(err.message)}};if(!modal.open)modal.showModal()}
function attr(raw){if(!String(raw).trim())return [];let v;try{v=JSON.parse(raw)}catch{return String(raw).split('\n').filter(Boolean).map(line=>{const i=line.indexOf(':');return i<0?[tidy(line),true]:[tidy(line.slice(0,i)),tidy(line.slice(i+1))]}).filter(x=>x[0])}const values=Array.isArray(v)?v:(v&&typeof v==='object')?Object.entries(v):[[String(v),true]];return [...new Map(values.flatMap(x=>Array.isArray(x)&&x.length>=2?[[tidy(x[0]),x[1]]]:typeof x==='object'&&x!==null?Object.entries(x).map(([k,v])=>[tidy(k),v]):[[tidy(x),true]]).filter(x=>x[0])).entries()]}
const targetNotes=(id)=>current().notes.filter(n=>n.targets.includes(id));
function notesMarkup(id){const a=targetNotes(id);return a.length?'<details><summary>'+a.length+' comment'+(a.length===1?'':'s')+'</summary>'+a.map(n=>'<p><b>'+e(n.author)+'</b> <small>'+e(new Date(n.at).toLocaleString())+' · '+e(n.part)+'</small><br>'+e(n.text).replace(/\n/g,'<br>')+(n.pref?' <span class="chip">'+e(n.pref)+'</span>':'')+'</p>').join('')+'</details>':''}
function comment(ids){if(!ids.length)return;const s=current();dlg('Comment on '+(ids.length===1?'this entry':ids.length+' entries'),area('Message (emoji welcome)','text')+field('Field or quote (optional)','part')+select('Preference','pref',['','Light preference','Strong preference','Light dislike','Strong dislike'],'')+'<label class="wide"><input type="checkbox" name="force"> Allow identical comment within 15 seconds</label>',f=>{if(!prose(f.text))return false;const txt=prose(f.text),part=tidy(f.part)||'General';if(!f.force&&s.notes.some(x=>x.text===txt&&x.part===part&&x.pref===f.pref&&x.device===device&&Date.now()-Date.parse(x.at)<15000&&x.targets.slice().sort().join()===ids.slice().sort().join())){alert('Duplicate within 15 seconds. Check the override to send it anyway.');return false}apply('Added comment',a=>a.notes.push({id:uid(),targets:[...new Set(ids)],text:txt,part,pref:f.pref,at:new Date().toISOString(),author:userSettings.nickname||'Member',device}));},'Post comment')}
const byId=(id)=>current().items.find(i=>i.id===id);
const tagsOf=(type)=>current().tags.filter(t=>!t.archived&&(!type||t.type===type));
const tagCheck=(ids)=>'<div class="wide chips">'+tagsOf().map(t=>'<label class="chip" style="background:'+safeColor(t.color)+'"><input name="tag:'+e(t.id)+'" type="checkbox" '+(ids.includes(t.id)?'checked':'')+'> '+e(t.name)+'</label>').join('')+'</div>';
const safeColor=x=>/^#[0-9a-f]{6}$/i.test(x)?x:colors[0];
const selectedTags=f=>Object.keys(f).filter(k=>k.startsWith('tag:')).map(k=>k.slice(4));
function descendants(id){const found=new Set([id]);let n=0;while(n!==found.size){n=found.size;for(const i of current().items)if(found.has(i.parent))found.add(i.id)}return found}
function itemEditor(id,clone=false){const s=current(), old=byId(id), item=old?copy(old):make({owner:filter.owner||'Shared',tags:filter.tag?[filter.tag]:[],parent:filter.parent});if(clone){item.id=uid();item.name+=' variant'}const ban=descendants(item.id);dlg(clone?'New item from template':old?'Edit entry':'Add an entry',field('Name','name',item.name)+select('Type','kind',[['item','Product / link'],['virtual','Virtual item / comparison'],['question','Question'],['text','Text / reference']],item.kind)+select('Who it’s for','owner',s.people,item.owner)+select('Decision','state',['Considering','Shortlisted','Bought','Different direction','Passed','Need replacement'],item.state)+field('Product URL','url',item.url,'url')+select('Parent group','parent',[['','Top level'],...s.items.filter(x=>x.kind==='virtual'&&!x.archived&&!ban.has(x.id)).map(x=>[x.id,x.name])],item.parent)+field('Unit price ($)','price',item.price??'','number')+field('Quantity','qty',item.qty,'number')+field('Store','store',item.store)+tagCheck(item.tags)+area('Description and decision notes','description',item.description)+area('Attributes (JSON object, key/value pairs, or one Key: value per line)','attributes',item.attributes.length?JSON.stringify(item.attributes,null,2):'')+'<label class="wide"><input name="allow" type="checkbox"> Allow a separate entry with the same name or product link</label>',f=>{const name=tidy(f.name), url=canonical(f.url);if(!name){alert('Add a name.');return false}if(f.url&&!url){alert('Use an HTTP or HTTPS link.');return false}if(!f.allow&&s.items.some(x=>x.id!==item.id&&(norm(x.name)===norm(name)||(url&&key(x.url)===key(url))))){alert('That name or link already exists. Use the existing entry or explicitly allow a separate one.');return false}if(f.price!==''&&(!Number.isFinite(+f.price)||+f.price<0)||!Number.isFinite(+f.qty)||+f.qty<0){alert('Price and quantity cannot be negative.');return false}Object.assign(item,{name,url,kind:f.kind,owner:f.owner,state:f.state,parent:f.parent,price:f.price===''?null:+f.price,qty:f.qty===''?1:+f.qty,store:tidy(f.store),tags:selectedTags(f),description:prose(f.description),attributes:attr(f.attributes)});apply((old&&!clone?'Edited ':'Added ')+name,a=>{const i=a.items.findIndex(x=>x.id===item.id);if(i<0)a.items.push(item);else a.items[i]=item});})}
function editTag(id,clone=false){const old=current().tags.find(t=>t.id===id); const t=old?copy(old):{id:uid(),name:'',color:colors[current().tags.length%colors.length],type:'category',mode:'ordered',notes:''};if(clone){t.id=uid();t.name+=' variant';t.archived=false}dlg(old&&!clone?'Edit category or tag':'Add category, tag or project',field('Name','name',t.name)+field('Color','color',safeColor(t.color),'color')+select('Type','type',['category','tag','project'],t.type)+select('Display mode','mode',['ordered','set','comparison'],t.mode)+area('Description','notes',t.notes)+'<label class="wide"><input name="allow" type="checkbox"> Allow another tag with this name</label>',f=>{const name=tidy(f.name);if(!name)return false;if(!f.allow&&current().tags.some(x=>x.id!==t.id&&norm(x.name)===norm(name))){alert('That name already exists.');return false}Object.assign(t,{name,color:safeColor(f.color),type:f.type,mode:f.mode,notes:prose(f.notes)});apply('Saved '+t.type+' '+name,s=>{const i=s.tags.findIndex(x=>x.id===t.id);i<0?s.tags.push(t):s.tags[i]=t});})}
function moveOrder(ids,way){apply('Reordered '+ids.length+' entries',s=>{const pick=new Set(ids), a=s.items, chosen=a.filter(x=>pick.has(x.id));if(way==='top'||way==='bottom'){const rest=a.filter(x=>!pick.has(x.id));s.items=way==='top'?[...chosen,...rest]:[...rest,...chosen]}else if(way==='up'){for(let i=1;i<a.length;i++)if(pick.has(a[i].id)&&!pick.has(a[i-1].id)&&a[i].parent===a[i-1].parent)[a[i-1],a[i]]=[a[i],a[i-1]]}else{for(let i=a.length-2;i>=0;i--)if(pick.has(a[i].id)&&!pick.has(a[i+1].id)&&a[i].parent===a[i+1].parent)[a[i+1],a[i]]=[a[i],a[i+1]]}})}
function bulk(ids){if(!ids.length)return;dlg('Change '+ids.length+' entries',select('Action','mode',[['add','Add tags / copy to category'],['remove','Remove tags'],['move','Move from selected category to chosen category'],['parent','Change group'],['hide','Hide'],['show','Unhide'],['archive','Archive'],['restore','Restore from archive'],['state','Change decision'],['top','Send to top'],['bottom','Send to bottom']],'add')+select('Group (for change group)','parent',[['','Top level'],...current().items.filter(i=>i.kind==='virtual'&&!i.archived).map(i=>[i.id,i.name])],'')+select('Decision (for change decision)','state',['Considering','Shortlisted','Bought','Different direction','Passed','Need replacement'],'Considering')+tagCheck([]),f=>{if(f.mode==='top'||f.mode==='bottom'){moveOrder(ids,f.mode);return}if(f.mode==='parent'&&ids.some(i=>descendants(i).has(f.parent))){alert('A group cannot go inside itself or a descendant.');return false}if(f.mode==='move'&&!filter.tag){alert('Choose the source category in the Tracker first.');return false}const tags=selectedTags(f);apply('Bulk '+f.mode+' on '+ids.length+' entries',s=>{for(const i of s.items.filter(x=>ids.includes(x.id))){if(f.mode==='add'||f.mode==='move')i.tags=[...new Set([...i.tags.filter(t=>f.mode!=='move'||t!==filter.tag),...tags])];if(f.mode==='remove')i.tags=i.tags.filter(t=>!tags.includes(t));if(f.mode==='parent')i.parent=f.parent;if(f.mode==='hide'||f.mode==='show')i.hidden=f.mode==='hide';if(f.mode==='archive'||f.mode==='restore')i.archived=f.mode==='archive';if(f.mode==='state')i.state=f.state}});})}
function guide(){return '<h2>Buying guide</h2>'+seed.guide.map(g=>'<section class="panel"><div class="eyebrow">'+e(g.owner)+'</div><h3>'+e(g.title)+'</h3>'+g.body.map(x=>'<p>'+e(x)+'</p>').join('')+(g.links||[]).map(([n,u])=>'<p><a href="'+e(link(u))+'" target="_blank" rel="noopener noreferrer">'+e(n)+'</a></p>').join('')+'</section>').join('')+button('goto','Open full tracker','items','primary')}
function cards(s){const q=norm(filter.q), byTag=s.tags.find(t=>t.id===filter.tag);const ids=filter.parent?descendants(filter.parent):null;const results=s.items.filter(i=>(prefs().hidden||!i.hidden)&&(prefs().archive||!i.archived)&&(!filter.tag||i.tags.includes(filter.tag))&&(!filter.owner||i.owner===filter.owner)&&(!ids||ids.has(i.id))&&(!q||norm([i.name,i.description,i.store,...i.attributes.map(([k,v])=>k+' '+JSON.stringify(v))].join(' ')).includes(q))).sort((a,b)=>(b.priority??0)-(a.priority??0));return '<div class="grid">'+results.map(i=>'<article class="card" draggable="true" data-card="'+e(i.id)+'" '+(i.hidden?'data-hidden':'')+'><label class="eyebrow"><input type="checkbox" data-pick="'+e(i.id)+'" '+(selected.has(i.id)?'checked':'')+'> '+e(i.owner)+' · '+e(i.kind)+' · '+e(i.archived?'Archived':i.state)+(i.priority!==undefined?' · priority '+e(i.priority):'')+'</label><h3>'+e(i.name)+'</h3>'+(i.parent?'<small class="child">↳ '+e(byId(i.parent)?.name||'Group')+'</small>':'')+'<p>'+e(i.description).replace(/\n/g,'<br>')+'</p>'+(link(i.url)?'<p><a target="_blank" rel="noopener noreferrer" href="'+e(link(i.url))+'">Open product or source ↗</a></p>':'')+(i.price!==null?'<p><b>'+money(i.price)+'</b> / unit · '+e(i.qty)+' planned</p>':'<p>Quantity: '+e(i.qty)+'</p>')+'<div class="chips">'+i.tags.map(id=>s.tags.find(t=>t.id===id)).filter(Boolean).map(t=>'<button class="chip" style="background:'+safeColor(t.color)+'" data-act="tag-filter" data-id="'+e(t.id)+'">'+e(t.name)+'</button>').join('')+'</div>'+(i.attributes.length?'<details><summary>Attributes & sources</summary><dl>'+i.attributes.map(([k,v])=>'<dt><b>'+e(k)+'</b> '+button('field-note','Annotate',i.id+'|'+k,'compact')+'</dt><dd>'+(typeof v==='string'&&link(v)?'<a href="'+e(link(v))+'" target="_blank" rel="noopener noreferrer">'+e(v)+'</a>':e(typeof v==='string'?v:JSON.stringify(v)))+'</dd>').join('')+'</dl></details>':'')+notesMarkup(i.id) +evidenceMarkup(i.id)+steeringMarkup(i.id)+'<div class="row actions">'+button('edit','Edit',i.id)+button('comment','Comment',i.id)+button('clone','Template',i.id)+button('up','↑',i.id)+button('down','↓',i.id)+button('inventory','Log',i.id)+button('research','Research','item|'+i.id)+button('summarize-item',i.kind==='virtual'?'Summarize tree':'Summarize',i.id)+button('evidence','Attach source',i.id)+button('variants','Variants',i.id)+(i.kind==='virtual'?button('group','View options',i.id)+button('decision-open','Compare options','group:'+i.id):'')+'</div></article>').join('')+'</div>'+(results.length?'':'<p>No matching entries.</p>')}
